<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_blog_setting( $c, $id, $default, $sanitize ) { $c->add_setting( $id, array( 'default' => $default, 'sanitize_callback' => $sanitize, 'transport' => 'refresh' ) ); }
function kimpu_blog_select_sanitizer( $allowed, $fallback ) { return function( $value ) use ( $allowed, $fallback ) { return array_key_exists( $value, $allowed ) ? $value : $fallback; }; }
function kimpu_register_blog_settings( $c ) {
    $c->add_panel( 'kimpu_blog_settings', array( 'title' => __( 'KimPu Blog Settings', 'kimpu-multipurpose' ), 'priority' => 26 ) );
    $c->add_section( 'kimpu_blog_layout', array( 'title' => __( 'Blog Layout', 'kimpu-multipurpose' ), 'panel' => 'kimpu_blog_settings' ) );
    $layout = array( 'grid' => __( 'Grid', 'kimpu-multipurpose' ), 'list' => __( 'List', 'kimpu-multipurpose' ), 'magazine' => __( 'Magazine', 'kimpu-multipurpose' ) );
    kimpu_blog_setting( $c, 'kimpu_blog_layout', 'grid', kimpu_blog_select_sanitizer( $layout, 'grid' ) ); $c->add_control( 'kimpu_blog_layout', array( 'label' => __( 'Blog Layout', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_layout', 'type' => 'select', 'choices' => $layout ) );
    foreach ( array( 'kimpu_blog_columns' => array( 3, array( 2 => '2', 3 => '3', 4 => '4' ), __( 'Column Count', 'kimpu-multipurpose' ) ), 'kimpu_blog_container_width' => array( 'default', array( 'default' => __( 'Theme Default', 'kimpu-multipurpose' ), 'wide' => __( 'Wide', 'kimpu-multipurpose' ), 'narrow' => __( 'Narrow', 'kimpu-multipurpose' ) ), __( 'Container Width', 'kimpu-multipurpose' ) ), 'kimpu_blog_sidebar_position' => array( 'right', array( 'right' => __( 'Right Sidebar', 'kimpu-multipurpose' ), 'left' => __( 'Left Sidebar', 'kimpu-multipurpose' ) ), __( 'Sidebar Position', 'kimpu-multipurpose' ) ) ) as $id => $data ) { $sanitize = is_int( $data[0] ) ? 'absint' : kimpu_blog_select_sanitizer( $data[1], $data[0] ); kimpu_blog_setting( $c, $id, $data[0], $sanitize ); $c->add_control( $id, array( 'label' => $data[2], 'section' => 'kimpu_blog_layout', 'type' => 'select', 'choices' => $data[1] ) ); }
    foreach ( array( 'kimpu_blog_featured' => __( 'Show Featured Article', 'kimpu-multipurpose' ), 'kimpu_blog_sidebar_enabled' => __( 'Enable Blog Sidebar', 'kimpu-multipurpose' ) ) as $id => $label ) { kimpu_blog_setting( $c, $id, 'kimpu_blog_featured' === $id, 'rest_sanitize_boolean' ); $c->add_control( $id, array( 'label' => $label, 'section' => 'kimpu_blog_layout', 'type' => 'checkbox' ) ); }
    kimpu_blog_setting( $c, 'kimpu_blog_sidebar_width', '280px', function( $v ) { return in_array( $v, array( '240px', '280px', '320px' ), true ) ? $v : '280px'; } ); $c->add_control( 'kimpu_blog_sidebar_width', array( 'label' => __( 'Sidebar Width', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_layout', 'type' => 'select', 'choices' => array( '240px' => '240px', '280px' => '280px', '320px' => '320px' ) ) );
    $c->add_section( 'kimpu_blog_cards', array( 'title' => __( 'Post Cards', 'kimpu-multipurpose' ), 'panel' => 'kimpu_blog_settings' ) );
    foreach ( array( 'image' => __( 'Show Images', 'kimpu-multipurpose' ), 'category' => __( 'Show Categories', 'kimpu-multipurpose' ), 'author' => __( 'Show Authors', 'kimpu-multipurpose' ), 'date' => __( 'Show Dates', 'kimpu-multipurpose' ), 'excerpt' => __( 'Show Excerpts', 'kimpu-multipurpose' ), 'reading_time' => __( 'Show Reading Time', 'kimpu-multipurpose' ) ) as $key => $label ) { $id = 'kimpu_blog_show_' . $key; kimpu_blog_setting( $c, $id, true, 'rest_sanitize_boolean' ); $c->add_control( $id, array( 'label' => $label, 'section' => 'kimpu_blog_cards', 'type' => 'checkbox' ) ); }
    $c->add_section( 'kimpu_blog_single', array( 'title' => __( 'Single Post', 'kimpu-multipurpose' ), 'panel' => 'kimpu_blog_settings' ) );
    $single_layout = array( 'full' => __( 'Full Width', 'kimpu-multipurpose' ), 'sidebar' => __( 'Content + Sidebar', 'kimpu-multipurpose' ), 'narrow' => __( 'Narrow Reading', 'kimpu-multipurpose' ) ); kimpu_blog_setting( $c, 'kimpu_blog_single_layout', 'narrow', kimpu_blog_select_sanitizer( $single_layout, 'narrow' ) ); $c->add_control( 'kimpu_blog_single_layout', array( 'label' => __( 'Single Post Layout', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_single', 'type' => 'select', 'choices' => $single_layout ) );
    foreach ( array( 'kimpu_blog_single_sidebar' => __( 'Enable Single Post Sidebar', 'kimpu-multipurpose' ), 'kimpu_blog_single_featured_image' => __( 'Show Featured Image', 'kimpu-multipurpose' ), 'kimpu_blog_toc_enabled' => __( 'Enable Table of Contents', 'kimpu-multipurpose' ), 'kimpu_blog_toc_h3' => __( 'Show H3 Headings in TOC', 'kimpu-multipurpose' ), 'kimpu_blog_toc_collapsible' => __( 'Collapsible Table of Contents', 'kimpu-multipurpose' ), 'kimpu_blog_reading_progress' => __( 'Enable Reading Progress', 'kimpu-multipurpose' ), 'kimpu_blog_author_box' => __( 'Show Author Box', 'kimpu-multipurpose' ), 'kimpu_blog_share' => __( 'Show Social Sharing', 'kimpu-multipurpose' ) ) as $id => $label ) { $default = in_array( $id, array( 'kimpu_blog_single_featured_image', 'kimpu_blog_toc_h3', 'kimpu_blog_toc_collapsible', 'kimpu_blog_author_box', 'kimpu_blog_share' ), true ); kimpu_blog_setting( $c, $id, $default, 'rest_sanitize_boolean' ); $c->add_control( $id, array( 'label' => $label, 'section' => 'kimpu_blog_single', 'type' => 'checkbox' ) ); }
    kimpu_blog_setting( $c, 'kimpu_reading_wpm', 200, function( $v ) { return max( 100, min( 1000, absint( $v ) ) ); } ); $c->add_control( 'kimpu_reading_wpm', array( 'label' => __( 'Reading Speed (words per minute)', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_single', 'type' => 'number', 'input_attrs' => array( 'min' => 100, 'max' => 1000, 'step' => 10 ) ) );
    $c->add_section( 'kimpu_blog_related', array( 'title' => __( 'Related Posts', 'kimpu-multipurpose' ), 'panel' => 'kimpu_blog_settings' ) ); kimpu_blog_setting( $c, 'kimpu_blog_related_enabled', true, 'rest_sanitize_boolean' ); $c->add_control( 'kimpu_blog_related_enabled', array( 'label' => __( 'Enable Related Posts', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_related', 'type' => 'checkbox' ) ); kimpu_blog_setting( $c, 'kimpu_blog_related_count', 3, function( $v ) { return max( 1, min( 12, absint( $v ) ) ); } ); $c->add_control( 'kimpu_blog_related_count', array( 'label' => __( 'Number of Related Posts', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_related', 'type' => 'number', 'input_attrs' => array( 'min' => 1, 'max' => 12 ) ) ); kimpu_blog_setting( $c, 'kimpu_blog_related_columns', 3, function( $v ) { return in_array( absint( $v ), array( 2, 3, 4 ), true ) ? absint( $v ) : 3; } ); $c->add_control( 'kimpu_blog_related_columns', array( 'label' => __( 'Related Post Columns', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_related', 'type' => 'select', 'choices' => array( 2 => '2', 3 => '3', 4 => '4' ) ) );
    $c->add_section( 'kimpu_blog_archives', array( 'title' => __( 'Archive Pages', 'kimpu-multipurpose' ), 'panel' => 'kimpu_blog_settings' ) ); kimpu_blog_setting( $c, 'kimpu_blog_archive_layout', 'grid', kimpu_blog_select_sanitizer( $layout, 'grid' ) ); $c->add_control( 'kimpu_blog_archive_layout', array( 'label' => __( 'Archive Layout', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_archives', 'type' => 'select', 'choices' => $layout ) ); kimpu_blog_setting( $c, 'kimpu_blog_archive_description', true, 'rest_sanitize_boolean' ); $c->add_control( 'kimpu_blog_archive_description', array( 'label' => __( 'Show Archive Description', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_archives', 'type' => 'checkbox' ) ); kimpu_blog_setting( $c, 'kimpu_blog_author_layout', 'profile', function( $v ) { return 'profile' === $v ? $v : 'profile'; } ); $c->add_control( 'kimpu_blog_author_layout', array( 'label' => __( 'Author Profile Layout', 'kimpu-multipurpose' ), 'section' => 'kimpu_blog_archives', 'type' => 'select', 'choices' => array( 'profile' => __( 'Profile Header', 'kimpu-multipurpose' ) ) ) );
}
